CREATE TABLE site_intake_observations(site_id text PRIMARY KEY REFERENCES sites(id) ON DELETE CASCADE,first_received_at timestamptz NOT NULL,last_received_at timestamptz NOT NULL,last_event_time timestamptz NOT NULL,last_generation bigint NOT NULL CHECK(last_generation>0),accepted_events bigint NOT NULL CHECK(accepted_events>0));
CREATE TABLE bot_observations(site_id text NOT NULL REFERENCES sites(id) ON DELETE CASCADE,day date NOT NULL,category text NOT NULL CHECK(category IN('ai','bot')),reason text NOT NULL CHECK(reason IN('ua','request_burst')),rule_id text NOT NULL CHECK(length(rule_id)<=64),rule_version integer NOT NULL CHECK(rule_version>0),filtered_requests bigint NOT NULL CHECK(filtered_requests>0),declared_events bigint NOT NULL CHECK(declared_events>=0),PRIMARY KEY(site_id,day,category,reason,rule_id,rule_version));
